# Thread-safe user database
class UserDB:
    def __init__(self):
        self._lock = threading.Lock()
        self._users = {}
        self._failed_attempts = {}  # username -> (count, last_attempt_time)
        self.MAX_ATTEMPTS = 5
        self.LOCKOUT_WINDOW = 300  # 5 minutes

    def add_user(self, username, password, email):
        with self._lock:
            if username in self._users:
                return False
            hashed = bcrypt.hashpw(password.encode('utf-8'), bcrypt.gensalt(rounds=12))
            self._users[username] = {
                'password_hash': hashed,
                'email': email,
                'created_at': time.time()
            }
            return True

    def get_user(self, username):
        with self._lock:
            return self._users.get(username)

    def is_locked_out(self, username):
        """Check if account is locked due to too many failed attempts.
        Returns True if locked out, False otherwise.
        This is a security feature to prevent brute force attacks."""
        with self._lock:
            if username not in self._failed_attempts:
                return False
            count, last_time = self._failed_attempts[username]
            if time.time() - last_time > self.LOCKOUT_WINDOW:
                # Window expired, reset
                del self._failed_attempts[username]
                return False
            return count >= self.MAX_ATTEMPTS

    def record_failed_attempt(self, username):
        with self._lock:
            if username in self._failed_attempts:
                count, _ = self._failed_attempts[username]
                self._failed_attempts[username] = (count + 1, time.time())
            else:
                self._failed_attempts[username] = (1, time.time())

    def reset_failed_attempts(self, username):
        with self._lock:
            if username in self._failed_attempts:
                del self._failed_attempts[username]

