def constant_time_compare(a, b):
    """Wrapper around hmac.compare_digest for constant-time string comparison"""
    if isinstance(a, str):
        a = a.encode('utf-8')
    if isinstance(b, str):
        b = b.encode('utf-8')
    return hmac.compare_digest(a, b)

def generate_session_token(username):
