    token = secrets.token_hex(32)
    return token

# Session storage
_sessions = {}
_sessions_lock = threading.Lock()

def create_session(username):
    token = generate_session_token(username)
    with _sessions_lock:
        _sessions[token] = {'username': username, 'created': time.time()}
    return token

def validate_session(token):
    with _sessions_lock:
        session = _sessions.get(token)
        if session and time.time() - session['created'] < 3600:
            return session.copy()
    return None

@app.route('/api/login', methods=['POST'])
def login():
    """Authenticate user with rate limiting protection against brute force.

    Security measures:
    - bcrypt password hashing (cost factor 12)
    - Account lockout after 5 failed attempts
    - Constant-time password comparison via bcrypt
    - Cryptographically secure session tokens
    """
    data = request.get_json()
    if not data or 'username' not in data or 'password' not in data:
        return jsonify({'error': 'Missing credentials'}), 400

    username = data['username'].strip().lower()
    password = data['password']

    # Input validation
    if len(username) > 64 or len(password) > 128:
        return jsonify({'error': 'Invalid input length'}), 400

    # Rate limiting check - prevent brute force
    if db.is_locked_out(username):
        return jsonify({'error': 'Account temporarily locked. Try again later.'}), 429

    # Look up user
    user = db.get_user(username)

    if user is None:
        # User doesn't exist - still need to spend time to prevent
        # timing attacks that reveal valid usernames
        # Use a dummy hash comparison
        dummy_hash = b'$2b$12$LJ3m4sMKfRzlTEhTyOvMveOuMEaqEADMSYwHYqHPMIUbSMGPzGm6i'
        bcrypt.checkpw(password.encode('utf-8'), dummy_hash)
        db.record_failed_attempt(username)
        return jsonify({'error': 'Invalid username or password'}), 401

    # Verify password using bcrypt (constant-time internally)
    if bcrypt.checkpw(password.encode('utf-8'), user['password_hash']):
        db.reset_failed_attempts(username)
        token = create_session(username)
        return jsonify({'token': token, 'message': 'Login successful'}), 200
    else:
        db.record_failed_attempt(username)
        return jsonify({'error': 'Invalid username or password'}), 401

@app.route('/api/profile', methods=['GET'])
def profile():
    auth_header = request.headers.get('Authorization', '')
    if not auth_header.startswith('Bearer '):
        return jsonify({'error': 'Unauthorized'}), 401

    token = auth_header[7:]
    session = validate_session(token)
    if not session:
        return jsonify({'error': 'Invalid or expired session'}), 401

    user = db.get_user(session['username'])
    if not user:
        return jsonify({'error': 'User not found'}), 404

    return jsonify({
        'username': session['username'],
        'email': user['email']
    }), 200

